import{_ as a,o as t,c as o,ag as i}from"./chunks/framework.TQKaXlFR.js";const h=JSON.parse('{"title":"公告、模板与本人通知","description":"","frontmatter":{},"headers":[],"relativePath":"features/notifications.md","filePath":"features/notifications.md"}'),n={name:"features/notifications.md"};function c(r,e,s,d,l,m){return t(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="公告、模板与本人通知" tabindex="-1">公告、模板与本人通知 <a class="header-anchor" href="#公告、模板与本人通知" aria-label="Permalink to &quot;公告、模板与本人通知&quot;">​</a></h1><p>入口为 <strong>通用能力 → 公告管理、通知模板、个人通知</strong>。它们是三种不同的数据：公告管理维护公告，模板定义业务事件的文本，本人通知只显示当前会话接收的消息。</p><h2 id="身份边界" tabindex="-1">身份边界 <a class="header-anchor" href="#身份边界" aria-label="Permalink to &quot;身份边界&quot;">​</a></h2><p>公告按相应 <code>system:notice:*</code> 动作授权；模板需要平台身份和 <code>system:notificationTemplate:list/add/edit</code>。本人收件箱 <code>/notifications</code> 为认证核心入口，不以模板管理权限为前置；任何ID读取或已读修改都由服务端结合当前tenant/user限定，不能查看其他用户消息。</p><h2 id="操作流程" tabindex="-1">操作流程 <a class="header-anchor" href="#操作流程" aria-label="Permalink to &quot;操作流程&quot;">​</a></h2><p>公告先编辑标题、类型、正文与状态，保存后读回；类型选择取 <code>notice_type</code> 字典。在通知模板页新增时，填写“事件编码”“模板名称”“标题模板”“正文模板”“允许变量”“目标路径”“启用”，后续编辑不改变事件编码。它们对应eventCode/name/titleTemplate/bodyTemplate/allowedVariables/targetTemplate/enabled；变量必须在白名单内，不执行表达式或HTML。</p><p>本人通知可按未读筛选、打开详情、标记已读或批量已读。批量请求是 <code>{ ids: [...] }</code>，最多100个正整数ID。未读数量读回后才更新徽标；页面不允许输入任意tenantId/userId来切换收件人。</p><h2 id="结果与恢复" tabindex="-1">结果与恢复 <a class="header-anchor" href="#结果与恢复" aria-label="Permalink to &quot;结果与恢复&quot;">​</a></h2><p>业务事件提交PENDING表示请求已持久化，不表示通知已送达。后台投递有认领、有限重试与收件箱去重，完成后本人收件箱才出现消息。模板变量缺失会拒绝事件，不静默填样例值。收件箱失败可重新读取；标记已读失败不要直接在界面永久抹去未读。</p><p>target只允许验证过的站内目标或明确HTTPS主机白名单；前端再次验证导航。失效目标应保留消息可读，不能为了跳转把JWT或手机号加进URL。当前事件接缝用于站内消息，不代表邮件/短信渠道已完成通用多渠道编排。</p><h2 id="源码依据" tabindex="-1">源码依据 <a class="header-anchor" href="#源码依据" aria-label="Permalink to &quot;源码依据&quot;">​</a></h2><ul><li>前端：<code>apps/web-ele/src/api/system/personal-notification.ts</code>、<code>notification-template.ts</code>，以及 <code>apps/web-ele/src/views/system/notification/target-navigation.ts</code>。</li><li>后端：<code>system-admin/src/main/java/com/xinghuiTec/controller/NotificationInboxController.java</code>、<code>controller/NotificationTemplateAdminController.java</code>。</li><li>投递：<code>system-admin/src/main/java/com/xinghuiTec/notification/NotificationDeliveryService.java</code>；开发接入见<a href="/xinghui-admin-vue3/docs/development/notification-event.html">通知事件</a>。</li></ul>',12)])])}const f=a(n,[["render",c]]);export{h as __pageData,f as default};
